    "15.1": [
      {"id": "wb-15.1-01", "type": "num", "diff": 1, "skill": "miles-km-table", "source": "wb", "lang": "en", "q": "The table shows approximate conversions: 5 miles = 8 km, 10 miles = 16 km, 15 miles = 24 km, 20 miles = 32 km. Following the pattern, how many kilometres is 35 miles?", "svg": null, "choices": null, "answer": 56, "accept": [], "tol": 0, "unitLabel": "km", "hints": ["Mỗi lần số dặm tăng thêm 5 thì số km tăng thêm bao nhiêu?", "35 dặm là bao nhiêu nhóm 5 dặm?", "Mỗi nhóm 5 dặm ứng với 8 km, vậy có bao nhiêu km?"], "explain": "35 dặm gồm 7 nhóm 5 dặm. Mỗi nhóm là 8 km nên 7 × 8 = 56 km.", "why": null},
      {"id": "wb-15.1-02", "type": "num", "diff": 1, "skill": "km-to-miles-flow", "source": "wb", "lang": "en", "q": "A flow chart converts kilometres to miles: Number of km → ÷ 8 → × 5 → Number of miles. Use it to convert 72 km into miles.", "svg": null, "choices": null, "answer": 45, "accept": [], "tol": 0, "unitLabel": "miles", "hints": ["Bước đầu tiên của sơ đồ là phép tính nào?", "72 ÷ 8 bằng bao nhiêu?", "Kết quả đó nhân với 5 thì được bao nhiêu?"], "explain": "72 ÷ 8 = 9, rồi 9 × 5 = 45. Vậy 72 km ≈ 45 dặm.", "why": null},
      {"id": "wb-15.1-03", "type": "num", "diff": 1, "skill": "miles-to-km-flow", "source": "wb", "lang": "en", "q": "A flow chart converts miles to kilometres: Number of miles → ÷ 5 → × 8 → Number of km. Use it to convert 135 miles into kilometres.", "svg": null, "choices": null, "answer": 216, "accept": [], "tol": 0, "unitLabel": "km", "hints": ["Dặm sang km thì ta chia cho số nào trước?", "135 ÷ 5 bằng bao nhiêu?", "Nhân kết quả đó với 8."], "explain": "135 ÷ 5 = 27, rồi 27 × 8 = 216. Vậy 135 dặm ≈ 216 km.", "why": null},
      {"id": "wb-15.1-04", "type": "mc", "diff": 2, "skill": "convert-direction", "source": "wb", "lang": "en", "q": "Use 5 miles ≈ 8 km to convert 120 km into miles. Which working is correct?", "svg": null, "choices": ["120 ÷ 8 × 5 = 75", "120 ÷ 5 × 8 = 192", "120 × 1.6 = 192", "120 ÷ 1.6 × 8 = 600"], "answer": 0, "accept": [], "tol": 0, "unitLabel": "", "hints": ["Số dặm nhiều hơn hay ít hơn số km cho cùng một quãng đường? (1 dặm dài hơn 1 km)", "Vậy kết quả phải lớn hơn hay nhỏ hơn 120?", "Trong mỗi 8 km có mấy dặm theo tỉ lệ 5 : 8?"], "explain": "120 ÷ 8 × 5 = 15 × 5 = 75 dặm. Các cách còn lại cho 192 hoặc 600, lớn hơn 120, là lỗi đổi ngược chiều: đã nhân với 8 thay vì 5.", "why": null},
      {"id": "wb-15.1-05", "type": "mc", "diff": 2, "skill": "compare-distance", "source": "wb", "lang": "en", "q": "Which is further, 180 miles or 296 km? (1 mile ≈ 1.6 km)", "svg": null, "choices": ["180 miles", "296 km", "They are the same distance"], "answer": 1, "accept": [], "tol": 0, "unitLabel": "", "hints": ["Để so sánh, em cần đưa cả hai về cùng một đơn vị. Em chọn đơn vị nào?", "180 dặm bằng bao nhiêu km?", "So sánh số km em vừa tìm với 296."], "explain": "180 × 1,6 = 288 km. Vì 296 km > 288 km nên 296 km dài hơn 180 dặm. So sánh trực tiếp 180 với 296 là sai vì đơn vị khác nhau.", "why": null},
      {"id": "wb-15.1-06", "howto": "Find the shortest round trip that starts in Lydenburg, visits all three towns and comes back. Enter its length in kilometres.", "type": "num", "diff": 3, "skill": "shortest-route", "source": "wb", "lang": "en", "q": "Sofia lives in Lydenburg. She must deliver parcels to Marble Hall, Sun City and Ngobi in any order, starting and finishing in Lydenburg. Distances in miles: Lydenburg–Marble Hall 60, Lydenburg–Sun City 75, Lydenburg–Ngobi 160, Marble Hall–Sun City 125, Marble Hall–Ngobi 210, Sun City–Ngobi 85. Work out the length of the shortest route in kilometres. (1 mile ≈ 1.6 km)", "svg": null, "choices": null, "answer": 688, "accept": [], "tol": 0, "unitLabel": "km", "hints": ["Có bao nhiêu thứ tự ghé thăm ba thành phố? Em liệt kê chúng thế nào cho khỏi sót?", "Với mỗi thứ tự, hãy cộng cả đoạn đi và đoạn về Lydenburg. Tuyến nào ngắn nhất?", "Đổi tổng số dặm của tuyến ngắn nhất sang km bằng cách nhân với 1,6."], "explain": "Có 6 thứ tự. Tuyến ngắn nhất là 430 dặm (ví dụ Lydenburg → Marble Hall → Sun City → Ngobi → Lydenburg: 60 + 125 + 85 + 160). 430 × 1,6 = 688 km.", "why": null},
      {"id": "wb-15.1-07", "type": "num", "diff": 2, "skill": "feet-to-metres", "source": "wb", "lang": "en", "q": "On Day 1 of their walk, Mia and Shen climbed up 250 feet, then 500 feet, then 750 feet (three separate climbs). Use 10 feet = 3 metres to work out the total height they climbed, in metres.", "svg": null, "choices": null, "answer": 450, "accept": [], "tol": 0, "unitLabel": "m", "hints": ["Tổng độ cao đã leo theo feet là bao nhiêu?", "1500 feet chứa bao nhiêu nhóm 10 feet?", "Mỗi nhóm 10 feet bằng 3 mét."], "explain": "250 + 500 + 750 = 1500 feet. 1500 ÷ 10 = 150 nhóm, 150 × 3 = 450 m.", "why": null},
      {"id": "wb-15.1-08", "howto": "Use the rule to find how long the whole walk should take. Enter the total time in minutes, not hours.", "type": "num", "diff": 3, "skill": "walk-time-rule", "source": "wb", "lang": "en", "q": "A walking-time rule says: total time = 1 hour for every 5 km walked + 1 hour for every 600 m climbed up. A walk is 15 miles long (1 mile ≈ 1.6 km) and climbs up 450 m in total. How many minutes should the walk take?", "svg": null, "choices": null, "answer": 333, "accept": [], "tol": 0, "unitLabel": "minutes", "hints": ["15 dặm bằng bao nhiêu km?", "Với 5 km mất 1 giờ = 60 phút, số km đó mất bao nhiêu phút? Với 600 m leo mất 60 phút, vậy 450 m mất bao nhiêu phút?", "Cộng thời gian đi bộ và thời gian leo."], "explain": "15 dặm = 24 km. Thời gian đi: 24 ÷ 5 × 60 = 288 phút. Thời gian leo: 450 ÷ 600 × 60 = 45 phút. Tổng 288 + 45 = 333 phút.", "why": null},
      {"id": "wb-15.1-09", "type": "num", "diff": 3, "skill": "car-value", "source": "wb", "lang": "en", "q": "Johannes bought a used car for $13 995 when its milometer read 8 935 miles. He sold it when the milometer read 45 605 miles. The car loses 5 cents in value for every kilometre driven. (1 mile ≈ 1.6 km.) What is the value of the car when he sells it, in dollars?", "svg": null, "choices": null, "answer": 11061.4, "accept": [], "tol": 0.01, "unitLabel": "$", "hints": ["Xe đã chạy bao nhiêu dặm trong thời gian anh sở hữu?", "Đổi số dặm đó sang km, rồi tính số xu mất giá (nhân 5). Đổi xu ra đô la thế nào?", "Lấy giá mua trừ đi số tiền mất giá."], "explain": "45 605 − 8 935 = 36 670 dặm = 58 672 km. Mất giá: 58 672 × 5 = 293 360 xu = 2 933,60 đô la. Giá trị: 13 995 − 2 933,60 = 11 061,40 đô la.", "why": null},
      {"id": "wb-15.1-10", "type": "num", "diff": 2, "skill": "km-to-miles-decimal", "source": "wb", "lang": "en", "q": "Convert 34 km into miles using 5 miles ≈ 8 km. Give your answer as a decimal.", "svg": null, "choices": null, "answer": 21.25, "accept": [], "tol": 0.001, "unitLabel": "miles", "hints": ["Đổi km sang dặm thì chia cho 8 rồi nhân với mấy?", "34 ÷ 8 bằng bao nhiêu (dạng thập phân)?", "Nhân kết quả với 5."], "explain": "34 ÷ 8 = 4,25 rồi 4,25 × 5 = 21,25 dặm (tức 21 1/4 dặm).", "why": null}
    ],
